import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"48、【井】 巽下坎上","description":"温公易说 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"温公易说 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"zh/classics/wengong/049.md","filePath":"zh/classics/wengong/049.md"}'),n={name:"zh/classics/wengong/049.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><h3 id="彖曰-巽乎水而上水-井。井养而不穷也。改邑不改井-乃以刚中也。汔至亦未繘井-未有功也。羸其瓶-是以凶也。" tabindex="-1">彖曰：巽乎水而上水，井。井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。 <a class="header-anchor" href="#彖曰-巽乎水而上水-井。井养而不穷也。改邑不改井-乃以刚中也。汔至亦未繘井-未有功也。羸其瓶-是以凶也。" aria-label="Permalink to “彖曰：巽乎水而上水，井。井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。”">​</a></h3><h3 id="象曰-木上有水-井。君子以劳民劝相。" tabindex="-1">象曰：木上有水，井。君子以劳民劝相。 <a class="header-anchor" href="#象曰-木上有水-井。君子以劳民劝相。" aria-label="Permalink to “象曰：木上有水，井。君子以劳民劝相。”">​</a></h3><h3 id="初六-井泥不食-旧井无禽-象曰-井泥不食-下也。旧井无禽-时捨也。" tabindex="-1">初六：井泥不食，旧井无禽 象曰：井泥不食，下也。旧井无禽，时捨也。 <a class="header-anchor" href="#初六-井泥不食-旧井无禽-象曰-井泥不食-下也。旧井无禽-时捨也。" aria-label="Permalink to “初六：井泥不食，旧井无禽 象曰：井泥不食，下也。旧井无禽，时捨也。”">​</a></h3><h3 id="九二-井谷射鲋-瓮敝漏-象曰-井谷射鲋-无与也。" tabindex="-1">九二：井谷射鲋，瓮敝漏 象曰：井谷射鲋，无与也。 <a class="header-anchor" href="#九二-井谷射鲋-瓮敝漏-象曰-井谷射鲋-无与也。" aria-label="Permalink to “九二：井谷射鲋，瓮敝漏 象曰：井谷射鲋，无与也。”">​</a></h3><p>谷穷也。穷于井中，所守隘也。射鲋于井，所获？也。瓮者，所以汲也。瓮敝而漏水，不可得也。</p><h3 id="九三-井渫不食-为我心恻-可用汲-王明并受其福-象曰-井渫不食-行恻也。求王明-受福也。" tabindex="-1">九三：井渫不食，为我心恻，可用汲，王明并受其福 象曰：井渫不食，行恻也。求王明，受福也。 <a class="header-anchor" href="#九三-井渫不食-为我心恻-可用汲-王明并受其福-象曰-井渫不食-行恻也。求王明-受福也。" aria-label="Permalink to “九三：井渫不食，为我心恻，可用汲，王明并受其福 象曰：井渫不食，行恻也。求王明，受福也。”">​</a></h3><h3 id="六四-井甃无咎-象曰-井甃无咎-修井也。" tabindex="-1">六四：井甃无咎 象曰：井甃无咎，修井也。 <a class="header-anchor" href="#六四-井甃无咎-象曰-井甃无咎-修井也。" aria-label="Permalink to “六四：井甃无咎 象曰：井甃无咎，修井也。”">​</a></h3><h3 id="九五-井洌寒泉-食-象曰-寒泉之食-中正也。" tabindex="-1">九五：井洌寒泉，食 象曰：寒泉之食，中正也。 <a class="header-anchor" href="#九五-井洌寒泉-食-象曰-寒泉之食-中正也。" aria-label="Permalink to “九五：井洌寒泉，食 象曰：寒泉之食，中正也。”">​</a></h3><p>井洌寒泉，食，居位用事而泽及于民之谓也。</p><h3 id="上六-井收勿幕-有孚-元吉-象曰-元吉在上-大成也。" tabindex="-1">上六：井收勿幕，有孚，元吉 象曰：元吉在上，大成也。 <a class="header-anchor" href="#上六-井收勿幕-有孚-元吉-象曰-元吉在上-大成也。" aria-label="Permalink to “上六：井收勿幕，有孚，元吉 象曰：元吉在上，大成也。”">​</a></h3>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
